@Composable
fun DoseRow(medicationName: String, doseLog: DoseLog, onClick: () -> Unit, modifier: Modifier = Modifier) {
    val formatter = remember { SimpleDateFormat("MMM d, h:mm a", Locale.getDefault()) }
    Row(
        modifier = modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .border(
                BorderStroke(1.dp, MaterialTheme.colorScheme.outline),
                RoundedCornerShape(12.dp),
            )
            .padding(vertical = 12.dp, horizontal = 16.dp),
    ) {
        Column {
            Text(medicationName, style = MaterialTheme.typography.titleMedium)
            Text(
                stringResource(
                    R.string.dose_at_time,
                    doseLog.doseAmount,
                    formatter.format(Date(doseLog.givenAtEpochMillis)),
                ),
                style = MaterialTheme.typography.bodyMedium,
            )
        }
    }
}
